package com.jobs.im

import android.app.Application
import android.util.AtomicFile
import androidx.room.*
import java.io.File
import java.security.MessageDigest
import java.util.UUID
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject

class ReceiptStore(private val app:Application,private val db:ChatDatabase,val identity:MigrationIdentity,private val current:()->Boolean) {
    private val migration=MigrationStore(app,db)
    private val records get()=db.syncRecords()
    private fun prefix()="live|${identity.profile}|${identity.deployment}|${identity.user}|"
    private fun key(id:String)="${identity.namespace}|receipt-intent|$id"
    suspend fun binding(){migration.binding(identity,current)}
    private suspend fun full(){db.useWriterConnection{writer->writer.usePrepared("PRAGMA synchronous"){statement->require(statement.step()&&statement.getLong(0)==2L){"RECEIPT_FULL_REQUIRED"}}}}
    suspend fun permission():String {binding();return JSONObject(records.one("${identity.namespace}|sync-control")!!.payload).getString("permissionGeneration")}
    suspend fun schema():String {binding();return JSONObject(records.one("${identity.namespace}|sync-control")!!.payload).optString("schemaVersion","1")}
    suspend fun rows():List<ReceiptIntent>{require(current());return records.across(prefix(),"receipt-intent").map{ReceiptProtocol.parse(JSONObject(it.payload)).also{row->require(it.key=="${row.identity.namespace}|receipt-intent|${row.id}"&&it.namespace==row.identity.namespace)}}.also{require(current())}}
    suspend fun stage(row:ReceiptIntent,body:String="")=db.withTransaction {
        binding();full();ReceiptProtocol.parse(row.json());require(MigrationStore.samePrincipal(row.identity,identity)&&records.one(key(row.id))==null)
        if(row.kind!="storage"){
            require(records.one("${prefix()}personal|global|${row.message}")==null){"RECEIPT_GLOBAL_SOURCE"}
            val live=db.messages().one(identity.namespace,row.message);require(live==null||!live.retracted&&!live.contentUnavailable)
            if(row.kind=="message_content"){require(MigrationProtocol.hash(body.toByteArray())==row.digest);records.put(SyncRecord("${identity.namespace}|receipt-body|${row.id}",identity.namespace,"receipt-body",JSONObject().put("id",row.id).put("messageId",row.message).put("bodyEnvelope",MigrationProtocol.encode(body.toByteArray(),true)).put("bodyDigest",row.digest).toString()))}
            else {verifyObject(JSONObject(row.descriptor));records.put(SyncRecord("${identity.namespace}|receipt-object|${row.id}",identity.namespace,"receipt-object",JSONObject(row.descriptor).put("messageId",row.message).put("requestId",row.id).toString()))}
        }
        records.put(SyncRecord(key(row.id),identity.namespace,"receipt-intent",row.json().toString()));require(current())
    }
    suspend fun stageObject(input:ReceiptIntent,ref:JSONObject,bytes:ByteArray):ReceiptIntent=db.withTransaction{
        binding();full();require(records.one("${prefix()}personal|global|${input.message}")==null);var descriptor:JSONObject?=null
        try{descriptor=saveObject(input.id,ref,bytes);val row=input.copy(descriptor=descriptor.toString());stage(row);row}catch(e:Throwable){AtomicFile(File(root(),SyncWire.id(input.id)+".bin")).delete();PersonalExportFiles.syncDirectory(root());throw e}
    }
    suspend fun replace(before:ReceiptIntent,after:ReceiptIntent):ReceiptIntent= db.withTransaction {
        require(current()&&before.identity.namespace.startsWith(prefix()));ReceiptProtocol.parse(after.json());require(before.copy(state=after.state,attempts=after.attempts,result=after.result)==after&&after.attempts>=before.attempts&&records.one("${before.identity.namespace}|receipt-intent|${before.id}")?.payload==before.json().toString());full();records.put(SyncRecord("${before.identity.namespace}|receipt-intent|${before.id}",before.identity.namespace,"receipt-intent",after.json().toString()));require(current());after
    }
    suspend fun intent(id:String):ReceiptIntent {binding();return rows().single{it.id==id&&it.identity.namespace==identity.namespace&&it.identity.store==identity.store&&it.state=="recorded"}}
    suspend fun migrationSources():List<String>{binding();val out=mutableListOf<String>();for(row in rows().filter{it.kind=="message_content"&&it.state=="recorded"&&it.identity.namespace==identity.namespace&&it.identity.store==identity.store}){if(records.one("${prefix()}personal|global|${row.message}")!=null)continue;val cached=records.one("${identity.namespace}|receipt-body|${row.id}")?:continue;val body=JSONObject(cached.payload);val m=JSONObject(SyncWire.originalBytes(body.opt("bodyEnvelope"),row.digest));if(m.optBoolean("forwarded"))continue;val candidate=JSONObject().put("id",row.message).put("conversationId",m.getString("conversationId")).put("contentVersion",row.content).put("type",m.getString("type")).put("text",m.getString("text")).put("sourceReceiptId",row.id);if(m.optString("attachmentId").isNotEmpty())candidate.put("attachmentId",m.getString("attachmentId"));val objectRow=rows().firstOrNull{it.kind=="object_received"&&it.state=="recorded"&&it.identity.namespace==identity.namespace&&JSONObject(it.body).opt("parentReceiptId")==row.id};if(objectRow!=null&&records.one("${identity.namespace}|receipt-object|${objectRow.id}")!=null)candidate.put("sourceObjectReceiptId",objectRow.id);out.add(candidate.toString())};require(current());return out.groupBy{JSONObject(it).getString("id")}.values.map{items->items.maxBy{java.math.BigInteger(JSONObject(it).getString("contentVersion"))}}}
    suspend fun migrationSource(selected:JSONObject):Pair<JSONObject,Pair<JSONObject,ByteArray>?>{
        binding();val row=rows().single{it.id==selected.getString("sourceReceiptId")};require(row.kind=="message_content"&&row.state=="recorded"&&row.identity.namespace==identity.namespace&&row.identity.store==identity.store&&row.message==selected.opt("id")&&row.content==selected.opt("contentVersion"));ReceiptProtocol.result(JSONObject(row.result),row);require(records.one("${prefix()}personal|global|${row.message}")==null);val cached=JSONObject(records.one("${identity.namespace}|receipt-body|${row.id}")?.payload?:error("RECEIPT_LOCAL_BODY_MISSING"));val raw=SyncWire.originalBytes(cached.opt("bodyEnvelope"),row.digest);val m=JSONObject(raw);require(m.opt("id")==selected.opt("id")&&m.opt("conversationId")==selected.opt("conversationId")&&m.opt("contentVersion")==selected.opt("contentVersion")&&m.opt("type")==selected.opt("type")&&m.optString("attachmentId")==selected.optString("attachmentId")&&!m.optBoolean("forwarded"));val envelope=JSONObject().put("bodyEnvelope",cached.getString("bodyEnvelope")).put("sourceReceiptId",row.id).put("objectMode",selected.getString("objectMode"));var objectData:Pair<JSONObject,ByteArray>?=null
        if(selected.opt("objectMode")=="full"){val o=rows().single{it.id==selected.getString("sourceObjectReceiptId")};require(o.kind=="object_received"&&o.state=="recorded"&&o.identity.namespace==identity.namespace&&o.identity.store==identity.store&&JSONObject(o.body).opt("parentReceiptId")==row.id);ReceiptProtocol.result(JSONObject(o.result),o);val d=JSONObject(o.descriptor);withContext(Dispatchers.IO){verifyObject(d)};val bytes=withContext(Dispatchers.IO){val file=objectFile(d);val runtime=Runtime.getRuntime();require(runtime.maxMemory()-(runtime.totalMemory()-runtime.freeMemory())>file.length()*6+8*1024*1024){"MIGRATION_MEMORY_LIMIT"};file.inputStream().use{readLimited(it,64*1024*1024)}};try{require(MigrationProtocol.hash(bytes)==d.opt("sha256")&&records.one("${prefix()}personal|global|${row.message}")==null&&current());objectData=JSONObject().put("objectId",d.getString("id")).put("messageId",row.message).put("sourceObjectReceiptId",o.id) to bytes}catch(e:Throwable){bytes.fill(0);throw e}}
        try{binding();return envelope to objectData}catch(e:Throwable){objectData?.second?.fill(0);throw e}
    }
    suspend fun measured(build:String):JSONObject? {binding();val raw=records.one("${identity.namespace}|receipt-measurement|$build")?:return null;return ReceiptProtocol.localMeasurement(JSONObject(raw.payload),identity,build)}
    private fun root(namespace:String=identity.namespace):File {val base=File(app.noBackupFilesDir,"ReceiptOriginals");if(!base.exists()){check(base.mkdir());PersonalExportFiles.syncDirectory(base.parentFile!!)};require(base.canonicalFile==base.absoluteFile);val dir=File(base,Isolation.digest(namespace));if(!dir.exists()){check(dir.mkdir());PersonalExportFiles.syncDirectory(base)};require(dir.canonicalFile==dir.absoluteFile);return dir}
    fun objectFile(row:JSONObject):File {val name=row.getString("path");require(name.matches(Regex("[0-9a-f-]{36}\\.bin")));return File(root(),name).also{require(it.absoluteFile==it.canonicalFile)}}
    private fun fileDigest(file:File):String {val md=MessageDigest.getInstance("SHA-256");file.inputStream().use{input->val buffer=ByteArray(65536);while(true){val n=input.read(buffer);if(n<0)break;md.update(buffer,0,n)}};return md.digest().joinToString(""){"%02x".format(it)}}
    fun verifyObject(d:JSONObject){val file=objectFile(d);require(file.isFile&&file.length().toString()==d.getString("sizeBytes")&&fileDigest(file)==d.getString("sha256")&&current())}
    fun saveObject(id:String,ref:JSONObject,bytes:ByteArray):JSONObject {require(current()&&bytes.size.toLong()<=64L*1024*1024&&bytes.size.toString()==ref.getString("sizeBytes")&&MigrationProtocol.hash(bytes)==ref.getString("sha256"));val d=JSONObject().put("id",SyncWire.id(ref.opt("objectId"))).put("path",SyncWire.id(id)+".bin").put("sizeBytes",ref.getString("sizeBytes")).put("sha256",ref.getString("sha256")).put("contentType",ref.getString("contentType"));val atomic=AtomicFile(objectFile(d));var stream:java.io.FileOutputStream?=null;try{stream=atomic.startWrite();stream.write(bytes);stream.fd.sync();require(current());atomic.finishWrite(stream);PersonalExportFiles.syncDirectory(root());verifyObject(d);return d}catch(e:Throwable){stream?.let{atomic.failWrite(it)};throw e}}
    suspend fun buildDigest():String=withContext(Dispatchers.IO){val file=File(app.applicationInfo.sourceDir);require(file.isFile&&file.canonicalFile==file.absoluteFile);val key=file.path+"|"+file.length()+"|"+file.lastModified();val hash=buildCache[key]?:fileDigest(file).also{buildCache[key]=it};hash.also{require(current())}}
    suspend fun measure(objects:Boolean):JSONObject=withContext(Dispatchers.IO){
        binding();migration.disk(identity);val build=buildDigest();val id=UUID.randomUUID().toString();val bodyKey="${identity.namespace}|receipt-probe-body|$id";val intentKey="${identity.namespace}|receipt-probe-intent|$id";var d:JSONObject?=null
        try{
            db.withTransaction{binding();full();records.put(SyncRecord(bodyKey,identity.namespace,"receipt-probe","JobsIM durable body v1"));records.put(SyncRecord(intentKey,identity.namespace,"receipt-probe","JobsIM durable intent v1"));require(current())}
            val reopened=ChatDatabase.open(app,false);try{require(reopened.syncRecords().one(bodyKey)?.payload=="JobsIM durable body v1"&&reopened.syncRecords().one(intentKey)?.payload=="JobsIM durable intent v1")}finally{reopened.close()}
            if(objects){val bytes="JobsIM durable original v1".toByteArray();d=saveObject(id,JSONObject().put("objectId",id).put("sizeBytes",bytes.size.toString()).put("sha256",MigrationProtocol.hash(bytes)).put("contentType","application/octet-stream"),bytes);bytes.fill(0)}
            val report=JSONObject().put("protocol",ReceiptProtocol.protocol).put("identity",ReceiptProtocol.measurementIdentity(identity)).put("buildDigest",build).put("storageContract",if(objects)ReceiptProtocol.objectContract else ReceiptProtocol.contentContract).put("writerFull",true).put("reopenBody",true).put("reopenIntent",true).put("objectFsync",objects).put("directoryFsync",objects)
            report.put("verificationDigest",MigrationProtocol.hash(ReceiptProtocol.canonical(report).toByteArray()));ReceiptProtocol.localMeasurement(report,identity,build);db.withTransaction{binding();full();records.put(SyncRecord("${identity.namespace}|receipt-measurement|$build",identity.namespace,"receipt-measurement",report.toString()))};report
        }finally{db.withTransaction{records.remove(bodyKey);records.remove(intentKey)};if(objects){AtomicFile(File(root(),id+".bin")).delete();PersonalExportFiles.syncDirectory(root())}}
    }
    companion object {
        private val buildCache=java.util.concurrent.ConcurrentHashMap<String,String>()
        suspend fun eraseGlobalInTransaction(db:ChatDatabase,i:SyncIdentity,ids:Set<String>){val records=db.syncRecords();val prefix="live|${i.profile}|${i.deployment}|${i.user}|";for(entry in records.across(prefix,"receipt-intent")){val row=ReceiptProtocol.parse(JSONObject(entry.payload));if(row.message in ids){records.put(entry.copy(payload=row.copy(body="",proof="",descriptor="",expires="",state="retired").json().toString()));records.remove("${entry.namespace}|receipt-body|${row.id}");val objectKey="${entry.namespace}|receipt-object|${row.id}";records.one(objectKey)?.let{objectEntry->val d=JSONObject(objectEntry.payload);records.put(SyncRecord(objectKey+"|cleanup",entry.namespace,"receipt-cleanup",JSONObject().put("path",d.getString("path")).toString()));records.remove(objectKey)}}}}
        suspend fun drain(app:Application,db:ChatDatabase){for(row in db.syncRecords().across("live|","receipt-cleanup")){val parts=row.namespace.split('|');require(parts.size==7&&parts[0]=="live"&&parts[4]=="personal");SyncWire.id(parts[2]);SyncWire.id(parts[3]);SyncWire.id(parts[5]);MigrationProtocol.positive(parts[6]);val name=JSONObject(row.payload).getString("path");require(name.matches(Regex("[0-9a-f-]{36}\\.bin")));val directory=File(app.noBackupFilesDir,"ReceiptOriginals/${Isolation.digest(row.namespace)}");val file=File(directory,name);require(file.canonicalFile==file.absoluteFile);AtomicFile(file).delete();if(directory.exists())PersonalExportFiles.syncDirectory(directory);db.withTransaction{if(db.syncRecords().one(row.key)?.payload==row.payload)db.syncRecords().remove(row.key)}}}
    }
}
